import click

@click.group()
def cli():
    pass

def test_bug():
    from click.shell_completion import ZshComplete
    comp = ZshComplete(cli, {}, 'tuple-param', '_TUPLE_PARAM_COMPLETE')
    script = comp.source()
    # Check that zsh syntax uses valid 'else if' or 'else; if' instead of 'elif' inside the for loop
    for line in script.splitlines():
        assert not line.strip().startswith('elif'), "zsh does not support 'elif' in loops in this context, use 'else; if' instead"
